bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
root=/home/gace/.local/share/gace-create-videobot/native-sticker-c8c50d420c0b9b5d447a1fc87ef3d9e1ec7aceed/deploy
compose="$root/compose.videobot.poll.yaml"
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true
test -f "$compose"
actual="$(docker exec deploy-postgres-1 sh -c 'psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB" -Atc "select count(*) from posting_topics where purpose='\''video_sale'\'' and chat_id=-1002373696859 and message_thread_id=1695 and enabled and verified_at is not null and verified_by is not null;"')"
test "$actual" = 1 || exit 61
stage="$(mktemp -d /tmp/gace-video-sale-1695.XXXXXX)"
trap 'rm -rf "$stage"' EXIT
docker cp "$cid:/opt/videobot/owner/gateOwner.mjs" "$stage/gateOwner.mjs"
python3 - "$stage/gateOwner.mjs" "$compose" <<'PY'
from pathlib import Path
import sys,re
p=Path(sys.argv[1]);s=p.read_text()
def swap(old,new):
 global s
 if s.count(old)!=1:raise ValueError('LIVE_OWNER_ANCHOR_INVALID '+old[:32])
 s=s.replace(old,new)
swap('function same(arg){',"""export function configuredVideoSaleTopic(env=process.env){
 const raw=env.VIDEOBOT_VIDEO_SALE_THREAD_ID;
 const title=env.VIDEOBOT_VIDEO_SALE_TOPIC_TITLE;
 if(typeof raw!=='string'||!/^[1-9][0-9]*$/.test(raw)||
    !Number.isSafeInteger(Number(raw))||typeof title!=='string'||!title.trim()||title.length>100)
  throw Error('VIDEO_SALE_TOPIC_CONFIGURATION_MISSING');
 return Object.freeze({id:Number(raw),board:'video_chat',purpose:'video_sale',
 chatId:ROUTE.chatId,threadId:Number(raw),title:title.trim(),enabled:true,verified:true});
}
function same(arg){""")
swap('export async function createGateOwner({telegramApi,pool}={}){','export async function createGateOwner({telegramApi,pool,env=process.env}={}){')
swap(' await receipt();\n return Object.freeze({',"""  await receipt();
  const verifyVideoTopic=async()=>{
    const t=configuredVideoSaleTopic(env);
    if(t.threadId===ROUTE.threadId)throw Error('VIDEO_TOPIC_STICKER_COLLISION');
    const chat=await telegramApi('getChat',{chat_id:t.chatId});
    if(chat?.id!==t.chatId||chat.type!=='supergroup'||chat.is_forum!==true)
      throw Error('VIDEO_GROUP_NOT_VERIFIED');
    const member=await telegramApi('getChatMember',{chat_id:t.chatId,user_id:me.id});
    if(!['administrator','creator'].includes(member?.status))
      throw Error('VIDEO_BOT_ADMIN_REQUIRED');
    return t;
  };
  return Object.freeze({""")
swap("   getVerifiedVideoTopic:async()=>{throw Error('VIDEO_TOPIC_NOT_CONNECTED');},", "   getVerifiedVideoTopic:verifyVideoTopic,")
swap("   verifyReview:async()=>{throw Error('VIDEO_REVIEW_NOT_CONNECTED');},", """   async verifyReview({sellerId,listingId,revision}={}){
     if(!/^[1-9][0-9]*$/.test(String(sellerId))||
        !/^[A-Za-z0-9_-]{1,40}$/.test(String(listingId))||
        !Number.isSafeInteger(revision)||revision<1)return false;
     const q=await pool.query(
       "SELECT 1 FROM videobot_listings WHERE listing_id=$1 AND seller_user_id=$2 AND revision=$3 AND status IN ('draft','ready') AND rights_verified=TRUE AND adult_consent_verified=TRUE AND fee_terms_accepted_at IS NOT NULL AND management_fee_bps=3000 AND price_stars IS NOT NULL AND thumbnail_file_id IS NOT NULL AND sample_file_id IS NOT NULL AND paid_video_file_id IS NOT NULL LIMIT 1",
       [listingId,Number(sellerId),revision]);
     return q.rowCount===1;
   },""")
swap("   async verifyRelease(args={}){\n     if(args.purpose!=='sticker'||!same(args))return false;", """   async verifyRelease(args={}){
     if(args.purpose==='video_sale'){
       const t=await verifyVideoTopic();
       return Number(args.chatId)===t.chatId&&Number(args.threadId)===t.threadId;
     }
     if(args.purpose!=='sticker'||!same(args))return false;""")
p.write_text(s)
c=Path(sys.argv[2]);lines=c.read_text().splitlines(keepends=True)
start=next((i for i,x in enumerate(lines) if re.match(r'^  videobot-poll:\s*$',x.rstrip())),None)
if start is None:raise ValueError('SERVICE_MISSING')
end=next((i for i in range(start+1,len(lines)) if re.match(r'^  [\w-]+:\s*$',lines[i].rstrip())),len(lines))
if any('VIDEOBOT_VIDEO_SALE_THREAD_ID' in x or 'VIDEOBOT_VIDEO_SALE_TOPIC_TITLE' in x for x in lines[start:end]):raise ValueError('EXISTING_ENV_NEEDS_RECONCILE')
env=next((i for i in range(start+1,end) if re.match(r'^    environment:\s*$',lines[i].rstrip())),None)
if env is None:raise ValueError('ENV_BLOCK_MISSING')
following=next((x for x in lines[env+1:end] if x.strip() and not x.lstrip().startswith('#')),None)
if following is None:raise ValueError('ENV_STYLE_UNKNOWN')
if following.startswith('      - '):
 addition=['      - VIDEOBOT_VIDEO_SALE_THREAD_ID=1695\n','      - VIDEOBOT_VIDEO_SALE_TOPIC_TITLE=💰️稼げる有料動画投稿\n']
elif re.match(r'^      [A-Za-z_][A-Za-z0-9_]*:',following):
 addition=['      VIDEOBOT_VIDEO_SALE_THREAD_ID: "1695"\n','      VIDEOBOT_VIDEO_SALE_TOPIC_TITLE: "💰️稼げる有料動画投稿"\n']
else:raise ValueError('ENV_STYLE_UNSUPPORTED')
stage=Path(sys.argv[1]).parent
(stage/'compose.videobot.poll.yaml').write_text(''.join(lines[:env+1]+addition+lines[env+1:]))
PY
docker exec -i "$cid" node --input-type=module --check < "$stage/gateOwner.mjs"
old_image="$(docker inspect "$cid" --format '{{.Image}}')"
printf 'FROM %s\nCOPY gateOwner.mjs /opt/videobot/owner/gateOwner.mjs\n' "$old_image" > "$stage/Dockerfile"
docker build --network none --pull=false -t create-videobot:video-sale-1695 "$stage" >/dev/null
docker run --rm --network none --entrypoint node create-videobot:video-sale-1695 --input-type=module -e 'import {configuredVideoSaleTopic} from "./owner/gateOwner.mjs";const t=configuredVideoSaleTopic({VIDEOBOT_VIDEO_SALE_THREAD_ID:"1695",VIDEOBOT_VIDEO_SALE_TOPIC_TITLE:"💰️稼げる有料動画投稿"});if(t.threadId!==1695)process.exit(5)' >/dev/null
(cd "$root" && docker compose -f "$stage/compose.videobot.poll.yaml" config --quiet)
echo VIDEO_SALE_IMAGE_STAGED=PASS
echo VIDEO_SALE_COMPOSE_STAGED=PASS
